package com.dataengine.governance.api;
import com.dataengine.governance.domain.GovernanceNotification; import com.dataengine.governance.service.NotificationService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/v1/notifications") public class NotificationController {private final NotificationService service;public NotificationController(NotificationService s){service=s;}@GetMapping public List<GovernanceNotification> inbox(@RequestParam(defaultValue="zhou.hang") String recipient){return service.inbox(recipient);}@GetMapping("/unread-count") public Map<String,Long> unread(@RequestParam(defaultValue="zhou.hang") String recipient){return Map.of("count",service.unread(recipient));}@PostMapping("/{id}/read")public GovernanceNotification read(@PathVariable UUID id){return service.markRead(id);}}
